## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;
  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;
  localparam int BIT_CLKS = 40;

  logic        clk = 1'b0;
  logic        rst = 1'b1;
  logic        rxd = 1'b1;
  logic        m_axis_tready = 1'b1;
  logic [15:0] prescale = PRESCALE;
  wire  [7:0]  m_axis_tdata;
  wire         m_axis_tvalid;
  wire         tx_busy, rx_busy;
  wire         rx_overrun_error, rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(8'h00),
    .s_axis_tvalid(1'b0),
    .s_axis_tready(),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1;
    wait_clks(4);
    rst = 1'b0;
    wait_clks(4);
  endtask

  // Send a byte with a 4-clock glitch on data bit `glitch_bit`.
  // The glitch pulses to the complement starting at clock 10 of the 40-clock
  // bit period. The DUT sample point is at clock 18, so the glitch edges
  // (clocks ~10 and ~14) are strictly before the sample (prescale_reg != 0).
  task automatic send_byte_with_glitch(input byte unsigned b, input int glitch_bit);
    rxd = 1'b0;
    wait_clks(BIT_CLKS);
    for (int i = 0; i < 8; i++) begin
      if (i == glitch_bit) begin
        rxd = b[i];
        wait_clks(10);
        rxd = ~b[i];
        wait_clks(4);
        rxd = b[i];
        wait_clks(26);
      end else begin
        rxd = b[i];
        wait_clks(BIT_CLKS);
      end
    end
    rxd = 1'b1;
    wait_clks(BIT_CLKS);
  endtask

  int unsigned deliveries = 0;
  always @(posedge m_axis_tvalid) deliveries++;

  initial begin
    do_reset();
    deliveries = 0;

    // Frame 1: 0xA5 with glitch on data bit 1 (bit value 0 -> 0,1,0)
    send_byte_with_glitch(8'hA5, 1);
    wait (deliveries >= 1);
    wait_clks(2);
    if (m_axis_tdata !== 8'hA5)
      $display("WARN: frame1 = 0x%02h (expected 0xA5)", m_axis_tdata);

    // Frame 2: 0x5A with glitch on data bit 2 (bit value 0 -> 0,1,0)
    send_byte_with_glitch(8'h5A, 2);
    wait (deliveries >= 2);
    wait_clks(2);
    if (m_axis_tdata !== 8'h5A)
      $display("WARN: frame2 = 0x%02h (expected 0x5A)", m_axis_tdata);

    #2000;
    $display("PASS R15");
    $finish;
  end

  initial begin
    #100ms;
    $fatal(1, "timeout");
  end

endmodule
```

